<param name="new_text">function buildExpanded(path: string, children: FileNode[], ctx: BuildCtx, depth: number): Box {
  const x = absX(depth);
  const w = ctx.containerWidth - x;
  const container = createBox('folder-container', { id: `expanded-${path}`, width: w, height: 0, x, y: 0 });
  container.border = { color: '#7c3aed', width: 1, sides: ['top', 'bottom', 'left', 'right'] };

  let cy = 0;
  if (children.length === 0) {
    const lr = createBox('file-row', { id: `loading-${path}`, x: TXT_L, y: cy, width: w - TXT_L, height: 32 });
    const lb = createBox('file-label', { id: `loading-label-${path}`, x: 0, width: lr.width - 8 });
    lb.textStyle = { ...TEXT_STYLES.fileLabel, content: '…', color: '#e0e0e0' };
    lr.addChild(lb); container.addChild(lr); cy += 32; container.height = cy; return container;
  }

  for (const item of children) {
    if (item.isDir) {
      const row = makeRow(item, cy, 0, ctx, true); cy += 32;
      // 重置行宽为容器宽度（不额外偏移）
      row.x = 0;
      if (ctx.expandedPaths[item.path]) {
        const ch = KFMState.files[item.path]?.children ?? item.children ?? [];
        const sub = buildExpanded(item.path, ch, ctx, depth + 1);
        sub.y = cy; container.addChild(sub); cy += sub.height;
      }
    } else {
      const row = makeRow(item, cy, 0, ctx, false); cy += 32;
      row.x = TXT_L;
    }
  }
  container.height = cy;
  return container;
}</param>
<param name="old_text">function buildExpanded(path: string, children: FileNode[], ctx: BuildCtx, depth: number): Box {
  const x = absX(depth);
  const w = ctx.containerWidth - x;
